import{_ as o,a8 as l,o as n,c as t,ah as c,K as r}from"./chunks/framework.B6ehkn__.js";import"./chunks/theme.BfMjDZ3-.js";const f=JSON.parse('{"title":"机器学习","description":"","frontmatter":{"title":"机器学习","abstract":"机器学习概览，涵盖人工智能三大概念的关系、常见术语、算法分类、建模流程与模型拟合问题。","created":"2026-03-28T00:00:00.000Z","tags":["机器学习","ML","概述"],"type":"概念解释","related":[],"reference":[],"category":["🤖 AI大模型","机器学习"]},"headers":[],"relativePath":"vault/Knowledge/AI/机器学习-概览.md","filePath":"vault/Knowledge/AI/机器学习-概览.md","lastUpdated":1790655645000}'),s={name:"vault/Knowledge/AI/机器学习-概览.md"};function p(d,a,u,b,h,g){const i=l("NolebaseGitContributors"),e=l("NolebaseGitChangelog");return n(),t("div",null,[a[0]||(a[0]=c('<h1 id="机器学习" tabindex="-1">机器学习 <a class="header-anchor" href="#机器学习" aria-label="Permalink to “机器学习”">​</a></h1><h1 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to “核心概念”">​</a></h1><ul><li><p>人工智能 三大概念</p><ul><li><p>人工智能、机器学习、深度学习</p></li><li><p>三者之间的关系</p><p><span data-type="text" style="background-color:var(--b3-card-warning-background);color:var(--b3-card-warning-color);">机器学习</span>是<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">实现人工智能的一种途径</span></p><p><span data-type="text" style="background-color:var(--b3-card-warning-background);color:var(--b3-card-warning-color);">深度学习</span>是<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">机器学习的一种方法</span></p></li></ul></li><li><p>*机器学习 应用领域和发展史</p><ul><li><p>机器学习的应用领域</p><ul><li>计算机视觉CV：对人看到的东西进行理解</li><li>自然语言处理：对人交流的东西进行理解</li><li>数据挖掘和数据分析：也属于人工智能的范畴</li></ul></li><li><p>人工智能发展史</p><ul><li>1956年 人工智能元年</li><li>2013年 计算机视觉深度神经网络方法研究兴起</li><li>2017年 自然语言处理应用大幕拉开</li><li>2022年 ChatGPT的出现，引起AIGC的发展</li></ul></li><li><p>AI 发展三要素</p><p>数据、算法、算力</p></li></ul></li></ul><h2 id="机器学习-常见术语" tabindex="-1">机器学习 常见术语 <a class="header-anchor" href="#机器学习-常见术语" aria-label="Permalink to “机器学习 常见术语”">​</a></h2><ul><li><strong>样本（Sample / Instance）：</strong> 一行数据</li><li><strong>特征（Feature）：</strong> 一列数据，即属性</li><li><strong>标签 / 目标值（Label / Target）：</strong> 要预测的那一列数据</li><li><strong>数据划分：</strong> 训练集（Train）、验证集（Validation）、测试集（Test）</li></ul><h2 id="机器学习-算法分类" tabindex="-1">机器学习 算法分类 <a class="header-anchor" href="#机器学习-算法分类" aria-label="Permalink to “机器学习 算法分类”">​</a></h2><p>按<span data-type="text" style="background-color:var(--b3-card-success-background);color:var(--b3-card-success-color);">学习范式</span>分类可分为：监督学习、无监督学习、半监督学习、强化学习</p><ul><li><p>监督学习：输入训练集数据包含输入特征值和目标值</p><ul><li>回归（Regression）：函数的输出是一个连续的值</li><li>分类（Classification）：函数的输出是有限个离散值</li></ul></li><li><p>无监督学习：输入训练集数据是由输入特征值组成、没有目标值</p><ul><li>比如：聚类（Clustering）根据样本间的相似性对样本集进行分类</li></ul></li><li><p>半监督学习：训练集同时包含有目标值的样本数据和不含有目标值的样本数据</p></li><li><p>强化学习：智能体不断与环境进行交互，通过获取最大奖励的方式（试错的方式）来获取最佳策略</p><p>主要包含四个元素：<code>Agent, Environment, Action, Reward</code>​</p></li></ul><p>按<span data-type="text" style="background-color:var(--b3-card-success-background);color:var(--b3-card-success-color);">系统实现方式</span>/<span data-type="text" style="background-color:var(--b3-card-success-background);color:var(--b3-card-success-color);">知识表示形式</span> 分类</p><ul><li><p>基于规则的学习</p></li><li><p>基于模型的学习（数据驱动的学习）</p></li></ul><h2 id="机器学习-建模流程" tabindex="-1">机器学习 建模流程 <a class="header-anchor" href="#机器学习-建模流程" aria-label="Permalink to “机器学习 建模流程”">​</a></h2><ol><li>获取数据：搜集与完成机器学习任务相关的数据集</li><li>数据基本处理：数据集中异常值、缺失值的处理等</li><li>特征工程：<code>特征提取 -&gt; 特征预处理 -&gt; 特征降维</code>​，让模型达到最好的效果</li><li>机器学习（模型训练）：选择合适的算法对模型进行训练</li><li>模型评估：评估效果好的上线服务，评估效果不好的则重复上述步骤</li><li>在线服务模型预测</li></ol><h2 id="模型拟合问题" tabindex="-1">模型拟合问题 <a class="header-anchor" href="#模型拟合问题" aria-label="Permalink to “模型拟合问题”">​</a></h2><ul><li><p>拟合：用来表示模型对样本分布点的模拟情况</p></li><li><p>过拟合、欠拟合<span data-type="text" style="background-color:var(--b3-card-success-background);color:var(--b3-card-success-color);">是什么</span></p><ul><li>过拟合：模型在训练集表现好、在测试集表现不好</li><li>欠拟合：模型在训练集、测试集表现都不好</li></ul></li><li><p>过拟合、欠拟合<span data-type="text" style="background-color:var(--b3-card-success-background);color:var(--b3-card-success-color);">出现的原因</span></p><ul><li>过拟合：模型太过于复杂、数据不纯、训练数据太少</li><li>欠拟合：模型过于简单</li></ul></li><li><p>泛化：具体的、个别的扩大为一般的能力</p></li></ul><p><span data-type="text" style="background-color:var(--b3-card-success-background);color:var(--b3-card-success-color);">模型的拟合情况 = 泛化能力</span></p><h1 id="特征工程" tabindex="-1">特征工程 <a class="header-anchor" href="#特征工程" aria-label="Permalink to “特征工程”">​</a></h1><ul><li><p>特征工程：利用专业背景知识和技巧处理数据，让模型效果更好</p></li><li><p>特征工程的内容：</p><ul><li><p>特征提取（Feature Extraction）</p></li><li><p>特征预处理（feature preprocessing）</p><blockquote><p>归一化（MinMaxScaler）</p></blockquote><blockquote><p>标准化（StandardScaler）</p></blockquote></li><li><p>特征降维（Feature Dimensionality）</p></li><li><p>特征选择（Feature Selection）</p></li><li><p>特征组合（Feature Crosses）</p></li></ul></li><li><p>【常用】特征提取和特征预处理</p></li></ul><h1 id="监督学习" tabindex="-1">监督学习 <a class="header-anchor" href="#监督学习" aria-label="Permalink to “监督学习”">​</a></h1><h3 id="knn算法" tabindex="-1">KNN算法 <a class="header-anchor" href="#knn算法" aria-label="Permalink to “KNN算法”">​</a></h3><ul><li><p>K近邻算法的思想：一个样本最相似的 k 个样本中的大多数属于某一个类别，则该样本也属于这个类别</p></li><li><p>K值的选择</p></li><li><p>K近邻算法分类流程 &amp; 回归流程</p></li></ul><h3 id="线性回归" tabindex="-1">线性回归 <a class="header-anchor" href="#线性回归" aria-label="Permalink to “线性回归”">​</a></h3><ul><li>利用 <span data-type="text" style="background-color:var(--b3-card-warning-background);color:var(--b3-card-warning-color);">回归方程(函数)</span> 对 <span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">一个或多个自变量(特征值)和因变量(目标值)之间</span> 关系进行建模的一种分析方式。</li></ul><h3 id="逻辑回归" tabindex="-1">逻辑回归 <a class="header-anchor" href="#逻辑回归" aria-label="Permalink to “逻辑回归”">​</a></h3><ul><li>利用 <span data-type="text" style="background-color:var(--b3-card-warning-background);color:var(--b3-card-warning-color);">Sigmoid 函数</span> 对 <span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">一个或多个自变量（特征值）与因变量（目标类别）之间</span> 的关系进行建模的一种<strong>分类模型</strong>。</li></ul><h3 id="决策树" tabindex="-1">决策树 <a class="header-anchor" href="#决策树" aria-label="Permalink to “决策树”">​</a></h3><p>一种<strong>基于树形结构的监督学习算法</strong>，用于解决<strong>分类</strong>（Classification）或<strong>回归</strong>（Regression）问题。</p><ul><li>ID3 决策树（信息增益）</li><li>C4.5 决策树（信息增益-&gt;信息增益率）</li><li>CART 决策树（回归：平方误差最小化，分类：基尼指数最小化）</li></ul><h3 id="集成学习" tabindex="-1">集成学习 <a class="header-anchor" href="#集成学习" aria-label="Permalink to “集成学习”">​</a></h3><p>集成学习 ≈ 多<u>基学习器</u> + 多样性保证 + 策略聚合</p><ul><li><p>随机森林 ≈ Bagging采样 + 特征随机 + 并行投票</p></li><li><p>AdaBoost ≈ 弱分类器 + 自适应加权 + 串行训练</p></li><li><p>GBDT ≈ 梯度提升 + 串行拟合残差 + 加法模型</p></li><li><p>XGBoost ≈ GBDT进阶 + 正则化约束 + 二阶泰勒优化 + 工程级加速</p></li><li><p><strong>三者递进关系：</strong> AdaBoost（加权调整样本） → <strong>GBDT</strong>（拟合残差/梯度） → <strong>XGBoost</strong>（带正则的GBDT）</p></li></ul><h1 id="无监督学习" tabindex="-1">无监督学习 <a class="header-anchor" href="#无监督学习" aria-label="Permalink to “无监督学习”">​</a></h1><h3 id="聚类" tabindex="-1">聚类 <a class="header-anchor" href="#聚类" aria-label="Permalink to “聚类”">​</a></h3><p>聚类 ≈ 无监督分组 + 相似性度量 + 簇内紧致 &amp; 簇间分离</p><ul><li>K-means ≈ 预设 K + k-means++ 初始化 + 迭代最小化 SSE</li></ul><h1 id="时间序列预测" tabindex="-1">时间序列预测 <a class="header-anchor" href="#时间序列预测" aria-label="Permalink to “时间序列预测”">​</a></h1><p>传统统计方法</p><ul><li>朴素法（Naive Method）</li><li>简单移动平均（Simple Moving Average, SMA）</li><li>移动平均法（Moving Average, MA）</li><li>简单指数平滑法（Simple Exponential Smoothing, SES）</li><li>霍尔特线性趋势法（Holt’s Linear Trend Method）</li><li>AR(p) 自回归模型（Autoregressive Model of Order p）</li><li>MA(q) 移动平均模型（Moving Average Model of Order q）</li><li>ARIMA 差分自回归移动平均模型（ARIMA(p, d, q)）</li></ul><h1 id="模型调优-超参数优化" tabindex="-1">模型调优（超参数优化） <a class="header-anchor" href="#模型调优-超参数优化" aria-label="Permalink to “模型调优（超参数优化）”">​</a></h1><h3 id="交叉验证-网格搜索" tabindex="-1">交叉验证 + 网格搜索 <a class="header-anchor" href="#交叉验证-网格搜索" aria-label="Permalink to “交叉验证 + 网格搜索”">​</a></h3><ul><li><p>交叉验证：是划分数据集的一种方法，目的是为了得到更加准确可信的模型评分</p></li><li><p>网格搜索：只需要将若干参数传递给网格搜索对象，它将自动完成不同超参数的组合、模型训练、模型评估，最终返回一组最优的超参数。</p></li><li><p>交叉验证 + 网格搜索（模型选择+参数调优）</p><ul><li>交叉验证解决<span data-type="text" style="background-color:var(--b3-card-error-background);color:var(--b3-card-error-color);">模型的数据输入问题（数据集划分）</span>得到更可靠的模型。</li><li>网格搜索解决<span data-type="text" style="background-color:var(--b3-card-error-background);color:var(--b3-card-error-color);">超参数的组合</span>。</li><li>两个组合再一起形成一个模型参数调优的解决方案。</li></ul></li></ul><p>【注】最后所给出的最优估计器对象，实际中不一定是最好的</p><h1 id="模型评估" tabindex="-1">模型评估 <a class="header-anchor" href="#模型评估" aria-label="Permalink to “模型评估”">​</a></h1><h3 id="分类评估" tabindex="-1">分类评估 <a class="header-anchor" href="#分类评估" aria-label="Permalink to “分类评估”">​</a></h3><ul><li><p>混淆矩阵：TP、FN、FP、TN</p></li><li><p>准确率：(真正例 + 真反例) / 样本总数</p></li><li><p>精确率：真正例 / 预测为正例</p></li><li><p>召回率：真正例 / 真实为正例</p></li><li><p>F1-score</p></li><li><p>AUC指标</p></li><li><p>ROC曲线</p></li></ul><h3 id="回归评估" tabindex="-1">回归评估 <a class="header-anchor" href="#回归评估" aria-label="Permalink to “回归评估”">​</a></h3><ul><li>平均绝对误差（Mean Absolute Error，MAE）</li><li>均方误差（Mean Squared Error，MSE）</li><li>均方根误差（Root Mean Squared Error，RMSE）</li></ul><h3 id="聚类评估" tabindex="-1">聚类评估 <a class="header-anchor" href="#聚类评估" aria-label="Permalink to “聚类评估”">​</a></h3><ul><li><p>SSE（Sum of Squared Errors，误差平方和）</p><p>内聚程度，越小越好</p></li><li><p>肘部法则，通过 SSE 确定 <code>n_clusters</code>​ 的值</p><p>K 增加，SSE 递减，SSE <span data-type="text" style="background-color:var(--b3-card-error-background);color:var(--b3-card-error-color);">下降速度明显放缓</span> -&gt; k为最佳值</p></li><li><p>SC 轮廓系数法（Silhoutte Coefficient）</p><p>簇内，聚合程度，越小越好；簇外，分离程度，越大越好</p></li><li><p>CH 指数（Calinski-Harabasz Index）</p><p>簇内，聚合程度，越小越好；簇外，分离程度，越大越好；K值，内聚程度，越小越好</p></li></ul><p>‍</p>',49)),r(i),r(e)])}const m=o(s,[["render",p]]);export{f as __pageData,m as default};
